/**
 * navdata.js — the precached airport / runway / navaid bundle.
 *
 * NO PANEL IN v1 CONSUMES THIS. The HSI and the nav pages are v2, gated behind
 * the attitude stability test. It is here because the bundle is precached by
 * the service worker and BITE has to be able to say whether it is present —
 * "the offline database is missing" is a real answer a pilot wants before
 * takeoff, not after.
 *
 * The file is generated by scripts/build-navdata.mjs from the OurAirports CSVs.
 * If it is absent, this reports absent. It does not fall back to a small
 * built-in table, which would be a synthetic navdata path wearing a helpful
 * face.
 */

import { bundleStatus } from './manifest.js';
import { greatCircleNm } from '../core/units.js';

export const NAVDATA_URL = '/data/navdata.json';

export async function loadNavdata(fetchImpl = fetch) {
  const status = await bundleStatus('navdata', fetchImpl);
  if (!status.present) {
    return { ok: false, reason: status.reason ?? 'navdata bundle not present', detail: status.detail ?? null };
  }
  try {
    const res = await fetchImpl(status.path ?? NAVDATA_URL, { cache: 'force-cache' });
    if (!res.ok) {
      return {
        ok: false,
        reason: `the data manifest says navdata is present but ${status.path ?? NAVDATA_URL} returned HTTP ${res.status}`,
      };
    }
    const body = await res.json();
    const counts = body?.meta?.counts;
    if (!body?.meta || !Array.isArray(body.airports)) {
      return { ok: false, reason: 'navdata bundle is present but malformed (no meta/airports)' };
    }
    return {
      ok: true,
      meta: body.meta,
      counts: counts ?? {
        airports: body.airports.length,
        runways: body.runways?.length ?? 0,
        navaids: body.navaids?.length ?? 0,
      },
      data: body,
    };
  } catch (err) {
    return { ok: false, reason: `navdata bundle unreadable: ${err.message}` };
  }
}

/**
 * Search the bundled airports for a type-ahead.
 *
 * EASY TO PICK means matching what someone actually types. A reader looking for
 * Sacramento Executive types "sacramento", or "KSAC", or "SAC" — so identifier,
 * name and municipality are all searched, and an identifier match outranks a
 * name match because someone typing four letters means the code.
 *
 * BIG AIRPORTS FIRST within a tier, because "san" should offer San Francisco
 * International before San Andreas' airstrip. That is a ranking, not a filter:
 * the small fields are still there, further down.
 */
const SIZE_RANK = { large_airport: 0, medium_airport: 1, small_airport: 2 };

export function searchAirports(airports, query, limit = 8) {
  const q = String(query ?? '').trim().toLowerCase();
  if (q.length < 2) return [];

  const scored = [];
  for (const a of airports ?? []) {
    // Every identifier this airport answers to. OurAirports splits them across
    // four columns and a reader does not know or care which one theirs is.
    const idents = [a.ident, a.icao_code, a.iata_code, a.gps_code, a.local_code]
      .filter((v) => typeof v === 'string' && v)
      .map((v) => v.toLowerCase());
    const name = (a.name ?? '').toLowerCase();
    const town = (a.municipality ?? '').toLowerCase();

    let tier = null;
    if (idents.some((i) => i === q)) tier = 0;              // exact code — they know it
    else if (idents.some((i) => i.startsWith(q))) tier = 1; // partial code
    else if (name.startsWith(q) || town.startsWith(q)) tier = 2;
    else if (name.includes(q) || town.includes(q)) tier = 3;
    if (tier === null) continue;

    scored.push({ a, tier, size: SIZE_RANK[a.type] ?? 3 });
  }

  scored.sort(
    (x, y) => x.tier - y.tier || x.size - y.size || (x.a.name ?? '').localeCompare(y.a.name ?? ''),
  );
  return scored.slice(0, limit).map((s) => s.a);
}

/**
 * A typed position, for "or another location".
 *
 * Accepts `38.68, -121.00` and the same with a degree sign or whitespace only.
 * Returns null for anything it cannot read RATHER THAN GUESSING — a
 * mis-parsed coordinate would centre the scope somewhere real and wrong, which
 * is worse than refusing.
 */
export function parseLatLon(text) {
  const m = String(text ?? '')
    .replace(/[°\s]+/g, ' ')
    .trim()
    .match(/^(-?\d+(?:\.\d+)?)[ ,]+(-?\d+(?:\.\d+)?)$/);
  if (!m) return null;
  const lat = Number(m[1]);
  const lon = Number(m[2]);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  if (Math.abs(lat) > 90 || Math.abs(lon) > 180) return null;
  return { lat, lon };
}

/**
 * The runways close enough to the scope's centre to be worth drawing.
 *
 * The bundle has carried 407
 * of them since 1.16.0 and nothing drew any — the airports were only ever a
 * type-ahead for the centre picker.
 *
 * REAL THRESHOLD COORDINATES, both ends, straight out of OurAirports. The line
 * on the scope is the runway where it actually is and pointing where it
 * actually points; nothing here is a symbol placed near an airport.
 *
 * CLOSED RUNWAYS ARE DROPPED. A closed runway drawn identically to an open one
 * is the panel asserting something false about a place, and this app's whole
 * contract is that it does not do that. A runway missing either threshold is
 * dropped for the same reason rather than being stubbed from the heading.
 *
 * Filtered by distance from the CENTRE, and the caller passes the display
 * range — so this returns what is on the scope, not what is in the region.
 */

/**
 * HOW SHORT A RUNWAY MAY BE AND STILL BE DRAWN, at each display range.
 *
 * ---------------------------------------------------------------------------
 * A REAL EFIS DECLUTTERS BY SIGNIFICANCE, NEVER BY COUNT
 * ---------------------------------------------------------------------------
 *
 * This used to keep the forty NEAREST runways and nothing else, which meant
 * widening the range showed you nothing new — it drew the same forty smaller.
 * Measured against the shipped bundle from its own declared reference point,
 * runways in range:
 *
 *     10 nm     1
 *     20 nm     9
 *     40 nm    36
 *     80 nm   107, of which 71 are beyond 40 nm
 *
 * So at 80 nm every one of those 71 distant fields was dropped in favour of
 * forty near ones, and the scope was the 40 nm scope drawn half-size. That is
 * what was reported from the device, and it was exactly right.
 *
 * A real display sheds the INSIGNIFICANT as it ranges out — it never hides a
 * major field because small strips happened to be nearer. Runway length is the
 * proxy for that and it is already on every record, so no join is needed.
 * Survivors with these floors: 1, 9, 29, 31 — roughly constant density, and at
 * 80 nm twenty-two of them are beyond 40 nm, so the fields finally reach the
 * edge of the scope. `airport-picker.test.mjs` asserts those four numbers
 * against the real bundle, so "nothing new appears at 80" cannot come back
 * silently.
 *
 * Ordered widest first so the lookup is a `find`.
 */
export const DECLUTTER_FLOORS_FT = Object.freeze([
  { rangeNm: 80, minLengthFt: 5000 },
  { rangeNm: 40, minLengthFt: 3000 },
  { rangeNm: 0, minLengthFt: 0 },
]);

/** The floor for a display range. Exported so the choice is testable without a
 *  browser — a canvas is invisible to the accessibility gate. */
export function minRunwayLengthFt(rangeNm) {
  return (DECLUTTER_FLOORS_FT.find((f) => rangeNm >= f.rangeNm) ?? DECLUTTER_FLOORS_FT.at(-1)).minLengthFt;
}

/**
 * The BACKSTOP, not the policy. The floors above are what actually declutters;
 * this only stops a dense metropolitan area painting a wall of marks. When it
 * bites it is reported to the caller rather than silently truncating — a scope
 * quietly showing a subset is the defect this whole change is about.
 */
export function runwaysNear(data, centre, rangeNm, limit = 120) {
  if (!centre || !Number.isFinite(centre.lat) || !Number.isFinite(centre.lon)) return [];
  const floor = minRunwayLengthFt(rangeNm);
  const out = [];
  for (const r of data?.runways ?? []) {
    if (r.closed) continue;
    // SIGNIFICANCE, at this range. A runway shorter than the floor is not drawn
    // — that is the room the distant fields need.
    if ((r.length_ft ?? 0) < floor) continue;
    if (!Number.isFinite(r.le_lat) || !Number.isFinite(r.le_lon)) continue;
    if (!Number.isFinite(r.he_lat) || !Number.isFinite(r.he_lon)) continue;
    // The midpoint, so a long runway half inside the ring still counts.
    const mid = { lat: (r.le_lat + r.he_lat) / 2, lon: (r.le_lon + r.he_lon) / 2 };
    const d = greatCircleNm(centre, mid);
    if (!(d <= rangeNm)) continue;
    out.push({
      ident: r.airport_ident,
      le: { lat: r.le_lat, lon: r.le_lon },
      he: { lat: r.he_lat, lon: r.he_lon },
      lengthFt: r.length_ft ?? null,
      distanceNm: d,
    });
  }
  out.sort((a, b) => a.distanceNm - b.distanceNm);
  const kept = out.slice(0, limit);
  // WHAT THE BACKSTOP DROPPED, said rather than swallowed. A non-enumerable
  // property, so every existing caller — and every test that deep-compares the
  // array — is untouched, while a caller that wants to report it can.
  if (out.length > kept.length) {
    Object.defineProperty(kept, 'dropped', { value: out.length - kept.length, enumerable: false });
  }
  return kept;
}
